    r = shop.insights.handle_lifetime_value("c1")
    assert (r.status, r.body) == (200, {"customer_id": "c1", "order_count": 0, "lifetime_value_cents": 0})


def test_lifetime_value_excludes_cancelled_and_uses_discounted_totals(shop):
    a = place(shop, "c1", ("PEN", 1)).body["order_id"]
    place(shop, "c1", ("LAMP", 2))  # 12000 -> 10_800
    place(shop, "c1", ("BOOK", 1))  # 2500
    place(shop, "c2", ("BOOK", 1))
    shop.orders.handle_cancel(a)
    r = shop.insights.handle_lifetime_value("c1")
    assert r.body == {"customer_id": "c1", "order_count": 2, "lifetime_value_cents": 13_300}


