    r = shop.insights.handle_order_history("c1")
    assert (r.status, r.body) == (200, {"customer_id": "c1", "orders": []})


def test_history_newest_first_with_discount_and_cancelled(shop):
    a = place(shop, "c1", ("PEN", 1)).body["order_id"]
    b = place(shop, "c1", ("LAMP", 2)).body["order_id"]  # 12000 -> 10% off
    place(shop, "c2", ("BOOK", 1))
    shop.orders.handle_cancel(a)
    r = shop.insights.handle_order_history("c1")
    assert r.status == 200
    assert r.body["orders"] == [
        {"order_id": b, "status": "placed", "total_cents": 10_800},
        {"order_id": a, "status": "cancelled", "total_cents": 300},
    ]
    for entry in r.body["orders"]:
        assert shop.orders.handle_get(entry["order_id"]).body["total_cents"] == entry["total_cents"]

